      "achados": [
        {
          "proposicao": "No contexto das auditorias internas do SGSO referidas pela Resolução ANP n° 43/2007, a fonte relata que procedimentos relacionados às operações, como partida, parada e isolamento de sistemas, devem estar atualizados.",
          "trechos": [
            "Ea944db7efcc2cc3a:0:696",
            "Ea944db7efcc2cc3a:696:1393"
          ],
