        {
          "proposicao": "A Engenharia de Manutenção é descrita como participante das análises de risco ainda nas fases de projeto, da especificação de equipamentos e da verificação de atendimento e adequação antes da entrada em produção.",
          "trechos": [
            "E195c5225c680a40c:700:1392"
          ],
