          ]
        },
        {
          "proposicao": "A camada de APC é apresentada como forma de reduzir variações do processo e permitir operação mais próxima dos limites operacionais por unidade.",
          "trechos": [
            "Ee76b368c3e1b4dfc:1399:2093"
